    function syncDocumentControls(){if(!state.root||!state.document)return;state.root.querySelectorAll('[data-doc]').forEach((input)=>{const key=input.dataset.doc;if(input.type==='checkbox')input.checked=Boolean(state.document[key]);else input.value=state.document[key]??'';});}
    function onRootChange(event){const docInput=event.target.closest?.('[data-doc]');if(docInput){const key=docInput.dataset.doc;state.document[key]=docInput.type==='checkbox'?docInput.checked:(docInput.type==='number'?num(docInput.value,state.document[key]):docInput.value);pushHistory();render();return;}const prop=event.target.closest?.('[data-prop]');if(!prop)return;const o=selectedObject();if(!o)return;const key=prop.dataset.prop;o[key]=prop.type==='checkbox'?prop.checked:(prop.type==='number'?num(prop.value,o[key]):prop.value);if(o.type==='botany-organ'&&key==='kind'){const style=organStyle(o.kind),size=defaultSize(o.kind);o.fill=style[0];o.stroke=style[1];o.width=size[0];o.height=size[1];o.label=o.kind.replace(/-/g,' ');}if(o.type==='botany-vessel'&&key==='kind'){const n=makeVessel(o.kind);o.stroke=n.stroke;o.textColor=n.textColor;o.lineWidth=n.lineWidth;o.dashed=n.dashed;o.label=o.kind;}pushHistory();render();}
