    function buildEditor(){if(state.root)return;addStyles();const root=document.createElement('div');root.className='qmx-botany-editor';root.hidden=true;root.innerHTML=`<div class="qmx-botany-shell" role="dialog" aria-modal="true" aria-label="Plant anatomy and botanical structure editor"><header class="qmx-botany-header"><div><div class="qmx-botany-title">Plant Anatomy / Botanical Structure Diagram</div><div class="qmx-botany-subtitle">Whole plants, roots, stems, leaves, flowers, tissues, vascular bundles, smart labels and transport arrows</div></div><div class="qmx-botany-actions"><button class="qmx-botany-btn" data-botany="new">New</button><button class="qmx-botany-btn" data-botany="undo">Undo</button><button class="qmx-botany-btn" data-botany="redo">Redo</button><button class="qmx-botany-btn" data-botany="duplicate">Duplicate</button><button class="qmx-botany-btn danger" data-botany="delete">Delete</button><button class="qmx-botany-btn" data-botany="close">×</button></div></header><main class="qmx-botany-main"><aside class="qmx-botany-panel"><strong>Botany tools</strong><div class="qmx-botany-tools" data-tools></div><div class="qmx-botany-section">Botanical presets</div><div class="qmx-botany-presets"><button class="qmx-botany-preset" data-preset="flowering-plant">Flowering plant</button><button class="qmx-botany-preset" data-preset="root-anatomy">Root anatomy</button><button class="qmx-botany-preset" data-preset="stem-section">Stem cross-section</button><button class="qmx-botany-preset" data-preset="leaf-section">Leaf cross-section</button><button class="qmx-botany-preset" data-preset="flower-anatomy">Flower anatomy</button><button class="qmx-botany-preset" data-preset="seed-germination">Seed germination</button><button class="qmx-botany-preset" data-preset="transport">Plant transport</button><button class="qmx-botany-preset" data-preset="photosynthesis">Photosynthesis</button><button class="qmx-botany-preset" data-preset="tissues">Tissue gallery</button><button class="qmx-botany-preset" data-preset="clear">Clear</button></div><p class="qmx-botany-subtitle">For a smart label, select Smart label, click a green connection point on a plant or structure, then click the label position.</p></aside><section class="qmx-botany-canvas-wrap"><div class="qmx-botany-canvas" data-canvas></div></section><aside class="qmx-botany-panel"><strong>Document</strong><div class="qmx-botany-field"><label>Title</label><input data-doc="title"></div><div class="qmx-botany-grid2"><div class="qmx-botany-field"><label>Width</label><input type="number" min="600" max="2400" data-doc="width"></div><div class="qmx-botany-field"><label>Height</label><input type="number" min="400" max="1800" data-doc="height"></div><div class="qmx-botany-field"><label>Grid size</label><input type="number" min="5" max="100" data-doc="gridSize"></div><div class="qmx-botany-field"><label>Background</label><input type="color" data-doc="background"></div></div><label class="qmx-botany-check"><input type="checkbox" data-doc="botanyShowGrid"> Show grid</label><label class="qmx-botany-check"><input type="checkbox" data-doc="botanyShowLabels"> Show smart labels</label><label class="qmx-botany-check"><input type="checkbox" data-doc="botanyShowBody"> Show whole-plant outline</label><label class="qmx-botany-check"><input type="checkbox" data-doc="botanyShowDetails"> Show botanical details</label><label class="qmx-botany-check"><input type="checkbox" data-doc="snap"> Snap to grid</label><hr><strong>Selected object</strong><div data-selected></div><div class="qmx-botany-summary" data-summary></div></aside></main><footer class="qmx-botany-footer"><div class="qmx-botany-status" data-status></div><div class="qmx-botany-actions"><button class="qmx-botany-btn" data-botany="export-svg">Export SVG</button><button class="qmx-botany-btn" data-botany="export-png">Export PNG</button><button class="qmx-botany-btn primary" data-botany="insert">Insert into question</button></div></footer></div>`;document.body.appendChild(root);state.root=root;state.canvas=root.querySelector('[data-canvas]');state.controls={tools:root.querySelector('[data-tools]'),selected:root.querySelector('[data-selected]'),summary:root.querySelector('[data-summary]'),status:root.querySelector('[data-status]'),undo:root.querySelector('[data-botany="undo"]'),redo:root.querySelector('[data-botany="redo"]')};TOOL_DEFS.forEach(([id,label,bn])=>{const b=document.createElement('button');b.className='qmx-botany-tool';b.dataset.tool=id;b.innerHTML=window.QmxDiagramToolButtonContent?window.QmxDiagramToolButtonContent(id,label,bn):`${esc(label)}<small>${esc(bn)}</small>`;state.controls.tools.appendChild(b);});root.addEventListener('click',onRootClick);root.addEventListener('change',onRootChange);state.canvas.addEventListener('pointerdown',onCanvasPointerDown);document.addEventListener('pointermove',onPointerMove,{passive:false});document.addEventListener('pointerup',onPointerUp);document.addEventListener('pointercancel',onPointerUp);document.addEventListener('focusin',(event)=>{if(isUsableTextarea(event.target))lastExternalTextarea=event.target;},true);document.addEventListener('keydown',onKeydown);}
    function open(context={}){buildEditor();state.context=context||{};state.sourceTextarea=resolveQuestionTextarea(state.context);state.document=state.context.initialSpec?Diagram.normalizeSpec(state.context.initialSpec):createDocument();if(state.document.mode!=='plant-anatomy')state.document=createDocument();state.selectedId=null;state.activeTool='select';state.interaction=null;state.labelStart=null;state.history=[];state.historyIndex=-1;pushHistory();syncDocumentControls();setTool('select',false);render();state.root.hidden=false;document.body.dataset.qmxBotanyOverflow=document.body.style.overflow||'';document.body.style.overflow='hidden';setStatus(state.context.initialSpec?'Existing plant anatomy diagram loaded.':'Choose a plant, structure, tissue, smart label, process arrow or preset.');}
